import { Column, CreateDateColumn, Entity, PrimaryColumn, Unique, UpdateDateColumn } from 'typeorm';
import type { User } from '../../modules/users/user.js';

export const USERS_EMAIL_UNIQUE = 'users_email_unique';

/** A user without their roles; those are `UserRoleEntity` rows. */
@Entity({ name: 'users' })
@Unique(USERS_EMAIL_UNIQUE, ['email'])
export class UserEntity implements Omit<User, 'roles'> {
  /** A UUIDv7 generated by the repository, so ids sort by creation time. */
  @PrimaryColumn({ type: 'uuid', primaryKeyConstraintName: 'users_pkey' })
  id!: string;

  @Column({ type: 'text' })
  email!: string;

  @Column({ name: 'password_hash', type: 'text' })
  passwordHash!: string;

  @Column({ type: 'text' })
  name!: string;

  @Column({ name: 'email_verified_at', type: 'timestamptz', nullable: true })
  emailVerifiedAt!: Date | null;

  @CreateDateColumn({ name: 'created_at', type: 'timestamptz' })
  createdAt!: Date;

  /** Set to the current time by every update. */
  @UpdateDateColumn({ name: 'updated_at', type: 'timestamptz' })
  updatedAt!: Date;
}
